  const inT = (dx, dz) => Math.max(Math.abs(dx), Math.abs(dz)) <= th && (!oct || Math.abs(dx) + Math.abs(dz) <= th + Math.floor(th / 2) + 1);
  const inTower = (x, z, m = 0) => hasTower && Math.abs(x - tcx) <= th + m && Math.abs(z - tcz) <= th + m;

