  const owner = (x, z) => { for (const v of vols) if (x >= v.x0 && x <= v.x1 && z >= v.z0 && z <= v.z1) return v; return inApse(x, z) ? apseVol : null; };
  const inside = (x, z) => owner(x, z) !== null;
