  sparse: { label: '疏', spacing: 42, gap: [4, 8], plot: [13, 17], spokes: 4, plaza: [15, 13], branch: 1.25 },
  normal: { label: '中', spacing: 34, gap: null, spokes: 6, plaza: [13, 11], branch: 1 },
