  const X0 = mx0 + ox, X1 = mx1 + ox, Z0 = mz0 + oz, Z1 = mz1 + oz;
  const cells = []; for (let x = X0 - 1; x <= X1 + 1; x++) for (let z = Z0 - 1; z <= Z1 + 1; z++) cells.push([x, z]);
  const [lfx, lfz] = facingOf((it.q || 0) + (LM ? LM.front || 0 : 0)), fore = [];
