    for (let x = X0; x <= X1; x++) for (let z = Z0; z <= Z1; z++) for (let k = 1; k <= LM.forecourt + 1; k++) { const a = x + lfx * k, b = z + lfz * k, q = a + ',' + b; if (!inR(a, b) && !seen.has(q) && T.inside(a, b)) { seen.add(q); fore.push([a, b]); } }
