    const x0 = Math.max(T.x0, Math.min(zn.x0, zn.x1)), x1 = Math.min(T.x1, Math.max(zn.x0, zn.x1)), z0 = Math.max(T.z0, Math.min(zn.z0, zn.z1)), z1 = Math.min(T.z1, Math.max(zn.z0, zn.z1));
